//! What stdarch declares versus what this binary can test, per extension.
//!
//! Generated by scripts/cpu/generate_tests.py - do not edit. Every architecture is
//! included, not just the one being compiled for: the interesting question is often
//! about a target you are not on ("how much of ARM32 NEON would this cover?").

use crate::cpu::{DroppedFunction, ExtensionCoverage};

/// Which compiler's stdarch these counts were taken from.
pub fn coverage_source() -> &'static str {
    "rustc 1.102.0-nightly (c7d5ba59d 2026-11-20)"
}

/// What each `DroppedFunction::reason` slug means, for a summary that groups by it.
pub fn drop_reasons() -> &'static [(&'static str, &'static str)] {
    &[
        ("deprecated", "deprecated upstream in favour of a non-intrinsic API"),
        ("excluded:deprecated", "Deprecated upstream in favour of a non-intrinsic API (core::hint::spin_loop, inline asm)."),
        ("excluded:does-not-exist", "Extracted from arm/neon.rs but not actually defined by stdarch (the extractor was confused by a doc comment or macro template naming the poly64 form next to the real one). stdarch defines only the _s64/_u64 forms of these shift-insert intrinsics - confirmed by grepping arm_shared/neon/generated.rs for \"fn vsli_n_p64\" versus \"fn vsli_n_s64\"."),
        ("excluded:privileged", "Supervisor-only (CPL0) - faults in user mode on every machine."),
        ("excluded:process-state-corruption", "State-restore / control-register writes: applying arbitrary buffer contents faults (#GP on an invalid MXCSR/XCR0) or corrupts the process state the test harness itself runs on."),
        ("excluded:unavailable-target-feature", "Calling these is undefined behaviour on this project's build: each is the AVX-VNNI / AVX-IFMA / SM3 / SM4 / SHA512 \"VEX-encoded on an AVX-512 part\" form, whose target feature the generated wrapper cannot enable without also enabling the AVX-512 encoding."),
        ("excluded:unstable-intrinsic", "The 128/256-bit AVX512VL forms of cvtepu32_ps need a nightly feature gate (stdarch_x86_avx512_vl_u32_to_f32_conversions) inside a stable group, and the x86 build has to keep compiling on stable for `cargo install`."),
        ("excluded:unsupported-signature", "aarch64 MTE: generic over a bare type parameter T on top of the OFFSET const generic (`__arm_mte_increment_tag<const OFFSET: i64, T>(src: *const T)`), which the generator has no substitution for - it emits a call missing the second generic argument, so this does not compile. MTE is also an optional ARMv8.5 extension real chips may not implement."),
        ("skipped-extension", "whole extension is not generated (unstable intrinsics or target feature)"),
        ("sve-gather-scatter", "SVE gather/scatter/prefetch: the address operand is a vector of per-lane pointers"),
        ("sve-pointer", "SVE load/store: sizing a buffer for a runtime-width vector is not designed yet"),
        ("sve-vector-length-dependent", "correct result depends on the hardware vector length, so no captured value can be valid"),
        ("unstable-type", "uses a type with no value helper in common/ (f16/bf16 lanes, multi-register tuples)"),
        ("x86-incompatible", "x86-only shape that does not compile for x86_64 (differing operand width)"),
    ]
}

